 * Exported so the rubric judges can include it too — every judge builds its
 * prompt through `buildUserPrompt`, but the standalone judges (evidence,
 * integrity, target fit) do not, and these commitments matter most to them.
 */
export function probeParticularsBlock(brief: ProjectBrief | null): string {
  const answered = (brief?.probes ?? []).filter(
    (p) => p.answer !== undefined && p.answer !== null,
  );
  if (answered.length === 0) return "";
  const lines = answered
    .map((p) => `- ${probeSummaryLine(p)}`)
    .filter((l) => !l.endsWith("→ "));
  if (lines.length === 0) return "";
  return `PARTICULARS (specific commitments the writer made during the interview — treat these as binding as the brief above)
${lines.join("\n")}

`;
}

function attachmentsBlock(brief: ProjectBrief | null): string {
  if (!brief?.attachments?.length) return "";

  let remainingTotal = 2000;
  const lines = brief.attachments.map((attachment) => {
    const header = `- [${attachment.kind === "link" ? "link" : "doc"}] "${attachment.title}" — ${attachment.why}`;
    if (attachment.kind !== "document" || !attachment.text?.trim()) {
      return header;
    }
    if (remainingTotal <= 0) {
      return `${header}\n  Excerpt omitted to keep prompt size bounded.`;
    }
    const excerpt = attachment.text.trim().slice(0, Math.min(500, remainingTotal));
    remainingTotal -= excerpt.length;
    const suffix =
      attachment.text.trim().length > excerpt.length
        ? "\n  [excerpt truncated]"
        : "";
    return `${header}\n  Excerpt:\n  """\n  ${excerpt.replace(/\n/g, "\n  ")}\n  """${suffix}`;
  });

  return `REFERENCE MATERIAL (writer-supplied, use to ground feedback; do not treat it as the draft itself)\n${lines.join("\n")}\n\n`;
}

function wordCount(text: string): number {
  return text.split(/\s+/).filter(Boolean).length;
}

function clampForContext(text: string, maxChars: number): string {
  if (text.length <= maxChars) return text;
  const head = text.slice(0, Math.floor(maxChars * 0.7));
  const tail = text.slice(-Math.floor(maxChars * 0.3));
  return `${head}\n\n[…draft trimmed for length…]\n\n${tail}`;
}

