import type { AiFeature } from "../src/types";
import type { AgentRequest } from "./agentPrompts";

interface CaptureServerAiGenerationArgs {
  feature: AiFeature;
  provider: string;
  model: string;
  req: AgentRequest;
  output?: string;
  latencyMs: number;
  temperature?: number;
  maxTokens?: number;
  spanName?: string;
  error?: unknown;
  evalSignals?: Record<string, unknown>;
}

const MAX_TEXT_CHARS = 6000;

function projectKey(): string | undefined {
  return process.env.POSTHOG_PROJECT_API_KEY ?? process.env.PUBLIC_POSTHOG_KEY;
}

function host(): string {
  return process.env.POSTHOG_HOST ?? "https://us.i.posthog.com";
}

function captureEnabled(): boolean {
  return process.env.POSTHOG_CAPTURE !== "false";
}

function clamp(text: string | undefined): string | undefined {
  if (!text) return text;
  if (text.length <= MAX_TEXT_CHARS) return text;
  return `${text.slice(0, MAX_TEXT_CHARS)}\n\n[truncated]`;
}

function id(prefix: string): string {
  return `${prefix}:${crypto.randomUUID()}`;
}

function errorValue(error: unknown): unknown {
  if (!error) return undefined;
  if (error instanceof Error) {
    return { message: error.message, name: error.name };
  }
  return String(error);
}

export async function captureServerAiGeneration({
  feature,
  provider,
  model,
  req,
  output,
  latencyMs,
  temperature,
  maxTokens,
  spanName,
  error,
  evalSignals,
}: CaptureServerAiGenerationArgs): Promise<void> {
  const apiKey = projectKey();
  if (!apiKey || !captureEnabled()) return;

  try {
    await fetch(`${host().replace(/\/$/, "")}/i/v0/e/`, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({
        api_key: apiKey,
        event: "$ai_generation",
        properties: {
          distinct_id: "convex-server",
          $ai_trace_id: id(feature),
          $ai_span_id: id(`${feature}:server-generation`),
          $ai_span_name: spanName ?? feature,
          $ai_model: model,
          $ai_provider: provider,
          $ai_input: [
            {
              role: "user",
              content: clamp(
                JSON.stringify({
                  persona: req.persona.id,
                  instruction: req.instruction ?? "feedback",
                  hasBrief: !!req.brief,
                  draftText: req.draftText,
                  anchor: req.anchor,
                  userMessage: req.userMessage,
                }),
              ),
            },
          ],
          $ai_output_choices: output
            ? [{ role: "assistant", content: clamp(output) }]
            : [],
          $ai_latency: latencyMs / 1000,
          $ai_temperature: temperature,
          $ai_max_tokens: maxTokens,
          $ai_is_error: !!error,
          $ai_error: errorValue(error),
          twyne_feature: feature,
          twyne_persona_id: req.persona.id,
          twyne_instruction: req.instruction ?? "feedback",
          twyne_server_runtime: "convex",
          ...evalSignals,
        },
      }),
    });
  } catch (err) {
    console.warn("[twyne:posthog] failed to capture AI generation:", err);
  }
}

import { afterAll, afterEach, describe, expect, test } from "bun:test";
import { lockBrowserGlobalsForTestFile } from "./test-browser-globals-lock";
import { DEFAULT_APPARATUS_SETTINGS, type AiSettings } from "../types";

type WindowLike = {
  localStorage: {
    getItem: (k: string) => string | null;
    setItem: (k: string, v: string) => void;
    removeItem: (k: string) => void;
    clear: () => void;
  };
};

const g = globalThis as unknown as {
  window?: WindowLike;
  indexedDB?: IDBFactory;
};
const originalWindow = globalThis.window;
const originalLocalStorage = globalThis.localStorage;
const releaseBrowserGlobalsLock = await lockBrowserGlobalsForTestFile();
// Another test file replaces `./idb` with a process-global Bun module mock.
// A cache-busted import gives this file the real implementation regardless of
// module evaluation order in the full parallel suite.
const {
  loadAiSettingsFromIdb,
  loadApparatusSettingsFromIdb,
  loadWriterSettingsFromIdb,
  saveAiSettingsToIdb,
  saveApparatusSettingsToIdb,
  saveWriterSettingsToIdb,
} = await import(`./idb?idb-preferences=${Date.now()}`);

const originalIndexedDb = g.indexedDB;
const localStorageStore: Record<string, string> = {};
const localStorageShim = {
  getItem: (k: string) => (k in localStorageStore ? localStorageStore[k] : null),
  setItem: (k: string, v: string) => {
    localStorageStore[k] = v;
  },
  removeItem: (k: string) => {
    delete localStorageStore[k];
  },
  clear: () => {
    for (const k of Object.keys(localStorageStore)) delete localStorageStore[k];
  },
};
const windowShim = {
  localStorage: localStorageShim,
};

function installStorage(): void {
  localStorageShim.clear();
  Object.defineProperty(globalThis, "window", {
    configurable: true,
    writable: true,
    value: windowShim,
  });
  Object.defineProperty(globalThis, "localStorage", {
    configurable: true,
    writable: true,
    value: localStorageShim,
  });
  Object.defineProperty(globalThis, "indexedDB", {
    configurable: true,
    writable: true,
    value: undefined,
  });
}

function installExplodingIndexedDb(): void {
  Object.defineProperty(globalThis, "indexedDB", {
    configurable: true,
    writable: true,
    value: {
      open: () => {
        throw new Error("IndexedDB should not be read before localStorage");
      },
    } as unknown as IDBFactory,
  });
}

afterEach(() => {
  try {
    g.window?.localStorage.clear();
  } catch {
    /* ignore */
  }
  if (originalWindow === undefined) {
    Reflect.deleteProperty(globalThis, "window");
  } else {
    Object.defineProperty(globalThis, "window", {
      configurable: true,
      writable: true,
      value: originalWindow,
    });
  }
  if (originalLocalStorage === undefined) {
    Reflect.deleteProperty(globalThis, "localStorage");
  } else {
    Object.defineProperty(globalThis, "localStorage", {
      configurable: true,
      writable: true,
      value: originalLocalStorage,
    });
  }
  if (originalIndexedDb === undefined) {
    Reflect.deleteProperty(globalThis, "indexedDB");
  } else {
    Object.defineProperty(globalThis, "indexedDB", {
      configurable: true,
      writable: true,
      value: originalIndexedDb,
    });
  }
});

afterAll(() => {
  releaseBrowserGlobalsLock();
});

